package com.mygordienko.grabbic.clip.adapter.db

import androidx.room.ConstructedBy
import androidx.room.Database
import androidx.room.RoomDatabase
import androidx.room.RoomDatabaseConstructor
import androidx.sqlite.driver.bundled.BundledSQLiteDriver
import com.mygordienko.grabbic.clip.domain.ClipSource
import kotlinx.coroutines.Dispatchers

@Database(entities = [ClipSource::class], version = 1, exportSchema = true)
@ConstructedBy(ClipSourceDatabaseConstructor::class)
abstract class ClipSourceDatabase: RoomDatabase() {
    abstract fun clipSourceDao(): ClipSourceDao
}

/**
 * Generated by Room (KSP)
 */
@Suppress("KotlinNoActualForExpect")
expect object ClipSourceDatabaseConstructor: RoomDatabaseConstructor<ClipSourceDatabase> {
    override fun initialize(): ClipSourceDatabase
}

/**
 * Builder instance is platform-specific, so each target platform MUST provide builder instance.
 */
fun getClipSourceDatabase(builder: RoomDatabase.Builder<ClipSourceDatabase>): ClipSourceDatabase {
    return builder
        .setDriver(BundledSQLiteDriver())
        .setQueryCoroutineContext(Dispatchers.IO)
        .build()
}